def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_def = 0
    for _, o in history:
        if o == 'D':
            opp_def += 1
    if opp_def == 0:
        return 'C'

    last_my, last_opp = history[-1]
    if last_opp == 'D':
        streak = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                streak += 1
            else:
                break
        if streak >= 5:
            return 'D'
        return 'C'
    else:
        if n >= 2 and history[-2][1] == 'D':
            streak = 0
            for i in range(n - 2, -1, -1):
                if history[i][1] == 'D':
                    streak += 1
                else:
                    break
            if streak >= 2:
                return 'D'
        return 'C'
